# -*- coding: utf-8 -*-
E(149,'Ce qui relève du hasard','On compare « lire le mois suivant sur un calendrier » et « lancer un dé équilibré ».',[
A('Laquelle de ces actions a un résultat qu’on ne peut pas prévoir avec certitude ?','Distinguer une règle déterminée et une expérience aléatoire.','Le dé peut tomber sur plusieurs faces sans qu’on sache laquelle à l’avance.','Le lancer de dé.','Identifier le hasard'),
A('Peut-on quand même connaître les résultats possibles du dé ?','Recenser les faces.','Un dé usuel porte les nombres 1, 2, 3, 4, 5 et 6.','Oui : 1 à 6.','Lister les possibilités')], 'Ne pas prévoir le résultat ne signifie pas ignorer les résultats possibles.')
E(149,'Possible, impossible ou certain','On lance un dé équilibré à six faces numérotées de 1 à 6.',[
A('Classer « obtenir 7 » et « obtenir moins de 7 ».','Comparer chaque condition aux six faces.','Aucune face ne porte 7 ; toutes les faces sont inférieures à 7.','Obtenir 7 : impossible ; moins de 7 : certain.','Examiner toutes les faces'),
A('Classer « obtenir 4 ».','Vérifier si certaines faces conviennent, mais pas toutes.','Seule la face 4 convient.','Possible, mais non certain.','Distinguer possible et certain')], 'Impossible correspond à une probabilité nulle ; certain à une probabilité égale à 1.')
E(149,'Un tirage parmi quatre jetons','Un sac opaque contient 1 jeton rouge et 3 jetons bleus indiscernables au toucher. On mélange avant de tirer un jeton.',[
A('Quelle est la probabilité de tirer rouge ?','Compter les jetons favorables parmi tous les jetons.','Un seul des quatre jetons est rouge.','1/4.','Former le quotient'),
A('Les deux couleurs ont-elles la même chance ?','Comparer leurs nombres de jetons.','Il y a trois jetons bleus contre un rouge.','Non : bleu est plus probable.','Vérifier l’équiprobabilité')], 'Deux couleurs possibles ne signifient pas deux couleurs équiprobables.', [('1/(1+3)',0.25)])
E(149,'La moitié des faces','On lance un dé équilibré à six faces.',[
A('Quelles faces donnent un nombre pair ?','Énumérer les faces avant de compter.','Les nombres pairs sont 2, 4 et 6.','2 ; 4 ; 6.','Recenser les cas favorables'),
A('Quelle est la probabilité d’obtenir un nombre pair ?','Diviser les cas favorables par les six faces équiprobables.',r'$3/6=1/2=0{,}5$.','1/2, soit 50 %.','Calculer et traduire')], 'On compte des faces, même si le résultat demandé est une propriété du nombre.', [('3/6',0.5),('50/100',0.5)])
E(149,'Une roue régulière','Une roue possède quatre secteurs de même angle : deux portent A, un porte B, un porte C. L’aiguille donne à chaque secteur la même chance.',[
A('Quelle est la probabilité d’obtenir A ?','Compter les secteurs, pas les lettres différentes.',r'$2/4=1/2$.','1/2.','Compter les secteurs favorables'),
A('Quelle lettre a le moins de chances de sortir ?','Comparer les parts de roue.','B et C occupent chacun un secteur. Elles sont à égalité.','B et C : 1/4 chacune.','Comparer les parts')], 'L’équiprobabilité concerne ici les secteurs, pas les lettres.', [('2/4',0.5),('1/4',0.25)],images=('roue_reguliere','roue_reguliere_corrige'))
E(149,'Une échelle de probabilités','On compare les nombres 0, 1/4, 1/2, 3/4 et 1.',[
A('Lesquels correspondent à impossible et certain ?','Utiliser les extrémités de l’échelle.','Aucune chance correspond à 0 ; toutes les chances correspondent à 1.','Impossible : 0 ; certain : 1.','Repérer les bornes'),
A('3/4 donne-t-il plus d’une chance sur deux ?','Comparer au même dénominateur.',r'$1/2=2/4$ et $3/4>2/4$.','Oui.','Comparer deux fractions')], 'Une probabilité est toujours comprise entre 0 et 1.', [('1/2',0.5),('2/4',0.5)])
E(149,'Une pièce ne se souvient pas','Une pièce équilibrée donne pile quatre fois de suite. On la relance dans les mêmes conditions.',[
A('Face est-il certain au prochain lancer ?','Chaque lancer recommence la même expérience.','Les quatre premiers résultats ne forcent pas le suivant.','Non.','Refuser une compensation obligatoire'),
A('Quelle est la probabilité de pile au prochain lancer ?','Conserver le modèle de la pièce équilibrée.','Pile et face ont toujours la même chance.','1/2.','Garder le même modèle')], 'Le hasard ne doit pas « rattraper » une série sur le lancer suivant.', [('1/2',0.5)])
E(149,'Des cartes numérotées','On tire au hasard une carte parmi 10 cartes indiscernables de dos, numérotées de 1 à 10.',[
A('Quelle est la probabilité d’obtenir un multiple de 3 ?','Lister les numéros qui conviennent.','Les numéros 3, 6 et 9 conviennent : trois cartes sur dix.','3/10, soit 30 %.','Lister avant de diviser'),
A('Quelle est la probabilité d’obtenir un numéro supérieur à 8 ?','Compter les cartes 9 et 10.','Deux cartes sur dix conviennent.','2/10 = 1/5, soit 20 %.','Compter une condition stricte')], '« Supérieur à 8 » n’inclut pas 8.', [('3/10',0.3),('2/10',0.2)])
E(149,'Une couleur ou une autre','Un sac contient 3 jetons rouges, 2 bleus et 5 verts. Tous sont indiscernables au toucher.',[
A('Quelle est la probabilité de rouge ou bleu ?','Réunir les deux couleurs sans les compter deux fois.',r'$(3+2)/10=5/10=1/2$.','1/2.','Regrouper les cas favorables'),
A('Quelle est la probabilité de ne pas obtenir vert ?','Reconnaître exactement les mêmes cas.','Ne pas être vert signifie être rouge ou bleu.','1/2 également.','Relier deux formulations')], 'Deux formulations peuvent décrire les mêmes résultats favorables.', [('(3+2)/10',0.5),('(3+2+5)',10)])
E(149,'Comparer deux sacs','A contient 2 rouges et 3 bleus ; B contient 3 rouges et 7 bleus. Chaque tirage est uniforme parmi les jetons du sac choisi.',[
A('Calculer la probabilité de rouge dans chaque sac.','Utiliser le total propre à chaque sac.',r'$2/5=0{,}4$ pour A ; $3/10=0{,}3$ pour B.','A : 40 % ; B : 30 %.','Calculer les deux quotients'),
A('Quel sac choisir pour avoir le plus de chances d’obtenir rouge ?','Comparer les probabilités, pas seulement les nombres de rouges.','A possède moins de rouges, mais ils représentent une plus grande part du sac.','A.','Choisir par proportion')], 'Le plus grand nombre de jetons favorables ne garantit pas la plus grande probabilité.', [('2/5',0.4),('3/10',0.3)])
E(149,'Des résultats observés','On lance une pièce équilibrée 20 fois et on observe 12 piles et 8 faces.',[
A('Quelle proportion des lancers a donné pile ?','Diviser le nombre de piles par le nombre de lancers.',r'$12/20=0{,}6$.','60 %.','Calculer la proportion observée'),
A('La probabilité théorique de pile devient-elle 60 % ?','Distinguer le modèle et cette série d’essais.','La pièce reste équilibrée : sa probabilité de pile vaut 50 %. Une série courte peut donner une autre proportion.','Non : elle reste 50 %.','Séparer observation et probabilité')], 'Un résultat observé sur une série ne remplace pas automatiquement le modèle.', [('12/20',0.6),('12+8',20)])
E(149,'Prévoir sans promettre','Un dé équilibré est lancé 60 fois. On s’intéresse au nombre 6.',[
A('Quelle est la probabilité d’obtenir 6 à un lancer ?','Une face favorable parmi six faces équiprobables.','Seule la face 6 convient.','1/6.','Compter une face'),
A('Est-il certain d’obtenir exactement dix fois 6 ?','Distinguer une proportion théorique d’un résultat imposé.',r'$60/6=10$ est un repère, mais chaque lancer reste aléatoire. Le nombre réel peut être différent.','Non.','Interpréter un repère')], 'Une probabilité ne garantit pas un nombre exact de succès sur une série finie.', [('60/6',10)])
E(149,'Une roue aux parts inégales','La moitié d’une roue porte A ; un quart porte B ; un quart porte C. La probabilité est proportionnelle à l’angle du secteur.',[
A('Donner les probabilités des trois lettres.','Lire les parts du disque.','A occupe une moitié ; B et C occupent chacun un quart.','A : 1/2 ; B : 1/4 ; C : 1/4.','Associer part et chance'),
A('Pourquoi 1/3 pour chaque lettre serait-il faux ?','Comparer les angles au lieu du seul nombre de lettres.','Les trois lettres n’occupent pas des secteurs de même angle.','Les lettres ne sont pas équiprobables.','Contrôler le modèle')], 'On ne divise par le nombre de couleurs que lorsqu’elles ont réellement la même chance.', [('1/2+1/4+1/4',1)],images=('roue_inegale','roue_inegale_corrige'))
E(149,'Un tableau de deux lancers','On lance deux fois une pièce équilibrée, dans les mêmes conditions. On distingue l’ordre des résultats.',[
A('Lister les résultats possibles.','Associer chaque premier résultat à chaque second résultat.','Après P, on peut avoir P ou F ; après F, on peut avoir P ou F.','PP ; PF ; FP ; FF.','Croiser deux étapes'),
A('Quelle est la probabilité d’obtenir exactement un pile ?','Compter les couples favorables parmi les quatre couples équiprobables.','PF et FP conviennent, soit deux couples sur quatre.','2/4 = 1/2.','Dénombrer des couples')], 'PF et FP sont deux résultats différents car l’ordre des lancers compte.', [('2*2',4),('2/4',0.5)],images=('deux_lancers','deux_lancers_corrige'))
E(149,'Corriger une probabilité impossible','Un élève trouve 7/6 pour la probabilité de gagner à un jeu.',[
A('Pourquoi peut-on détecter une erreur sans connaître le jeu ?','Utiliser l’encadrement des probabilités.',r'$7/6>1$, alors qu’une probabilité ne dépasse jamais 1.','Le résultat est impossible.','Contrôler les bornes'),
A('Quelle vérification proposer ?','Comparer le nombre de cas favorables au nombre total.','Les cas favorables doivent faire partie des cas possibles ; ils ne peuvent pas être plus nombreux que le total.','Recompter les deux nombres et vérifier le quotient.','Rechercher la source de l’erreur')], 'Un contrôle de vraisemblance peut révéler une erreur avant un recalcul détaillé.')
E(149,'Un jeu équitable','Dans une urne, 4 jetons portent G et 6 portent P. Tous les jetons ont la même chance. On gagne si on tire G.',[
A('La probabilité de gagner vaut-elle une chance sur deux ?','Comparer l’effectif gagnant à la moitié du total.',r'$4/10=0{,}4$, inférieur à 0,5.','Non : 40 %.','Calculer la chance de gain'),
A('Combien de jetons G ajouter pour obtenir autant de G que de P ?','Égaliser les deux effectifs sans changer les P.',r'$6-4=2$. Avec 6 G et 6 P, on a une chance sur deux.','2 jetons G.','Modifier la composition')], 'Lorsqu’on ajoute des jetons, le nombre total change aussi.', [('4/10',0.4),('6-4',2),('6/12',0.5)])
E(149,'Observer un sac inconnu','Un sac contient des jetons rouges et bleus. Après mélange et remise du jeton après chaque tirage, on observe 31 rouges en 50 tirages.',[
A('Quelle proportion de rouges a-t-on observée ?','Rapporter les succès au nombre d’essais.',r'$31/50=0{,}62$.','62 %.','Calculer une proportion expérimentale'),
A('Peut-on affirmer que le sac contient exactement 62 % de rouges ?','Tenir compte des fluctuations de l’échantillon.','Le relevé donne une indication, mais une autre série pourrait donner un résultat différent.','Non.','Éviter une certitude abusive')], 'Remettre le jeton et mélanger conserve les mêmes conditions à chaque tirage.', [('31/50',0.62)])
E(149,'Changer la composition','Un sac contient 3 rouges et 3 bleus. On ajoute 2 rouges.',[
A('Quelle était la probabilité de rouge ?','Compter le total initial.',r'$3/(3+3)=1/2$.','1/2.','Étudier le sac initial'),
A('Quelle est la nouvelle probabilité ?','Actualiser le numérateur et le dénominateur.',r'$(3+2)/(3+3+2)=5/8$. Elle est supérieure à 1/2.','5/8.','Étudier le sac modifié')], 'Ajouter deux rouges ne signifie pas ajouter 2 à la probabilité.', [('3/(3+3)',0.5),('(3+2)/(3+3+2)',0.625)])
E(149,'Sans remise','Un sac contient 2 rouges et 1 bleu. On tire un jeton rouge et on le garde hors du sac.',[
A('Que reste-t-il dans le sac ?','Actualiser les effectifs après le retrait.','Un rouge et un bleu restent.','2 jetons : 1 rouge et 1 bleu.','Décrire le nouvel état'),
A('Quelle est alors la probabilité de rouge au prochain tirage uniforme ?','Utiliser la composition actuelle.','Un des deux jetons restants est rouge.','1/2.','Calculer après retrait')], 'Sans remise, les conditions peuvent changer ; avec remise, la composition est conservée.', [('(2-1)+1',2),('1/2',0.5)])
E(149,'Au moins un pile','On lance deux fois une pièce équilibrée ; les quatre couples PP, PF, FP et FF ont la même chance.',[
A('Quels couples donnent au moins un pile ?','Inclure un ou deux piles.','PP, PF et FP conviennent ; seul FF ne convient pas.','PP ; PF ; FP.','Lire « au moins »'),
A('Calculer la probabilité.','Compter les couples favorables.',r'$3/4=0{,}75$.','3/4, soit 75 %.','Traduire le dénombrement')], '« Au moins un » comprend aussi « deux », contrairement à « exactement un ».', [('3/4',0.75)],images=('deux_lancers','au_moins_un'))
E(149,'Comparer deux séries','Pour un jeu dont la probabilité de gain vaut 1/4, A gagne 4 fois en 20 parties et B gagne 27 fois en 100 parties, dans les mêmes conditions.',[
A('Calculer les proportions de gains.','Rapporter les succès à chaque nombre de parties.',r'$4/20=0{,}20$ et $27/100=0{,}27$.','A : 20 % ; B : 27 %.','Calculer deux observations'),
A('Quelle série est la plus proche de 25 % ? Cela prouve-t-il que le jeu est truqué ?','Comparer les écarts puis interpréter prudemment.','A s’écarte de 5 points de pourcentage et B de 2 points. Ces écarts ne prouvent pas une tricherie.','B est plus proche ; aucune preuve de trucage.','Confronter données et modèle')], 'Une série plus longue tend à stabiliser les proportions, sans garantir une égalité exacte.', [('4/20',0.2),('27/100',0.27),('25-20',5),('27-25',2)])

# Informatique sans images de code ; codages globaux et relatifs explicitement séparés.
E(152,'Reconnaître une instruction','Une personne reçoit : « avancer d’une case ; tourner à gauche ; avancer de deux cases ».',[
A('Combien d’instructions contient la séquence ?','Compter les ordres élémentaires dans l’ordre.','Avancer, tourner et avancer sont trois ordres distincts.','3.','Décomposer la séquence'),
A('Pourquoi faut-il respecter l’ordre ?','Chaque ordre agit sur la position ou l’orientation atteinte.','Tourner avant ou après le déplacement peut changer la direction suivie.','L’ordre peut changer le résultat.','Comprendre la séquence')], 'Une séquence est une liste ordonnée d’instructions.')
E(152,'Entrée et sortie','Un programme demande un nombre puis affiche le double de ce nombre.',[
A('Identifier l’entrée et la sortie.','Distinguer la donnée fournie du résultat affiché.','L’utilisateur fournit le nombre ; le programme calcule et affiche son double.','Entrée : nombre saisi ; sortie : son double.','Suivre les informations'),
A('Quelle sortie donne l’entrée 7 ?','Exécuter le calcul indiqué.',r'$2\times7=14$.','14.','Calculer la sortie')], 'Une entrée n’est pas déjà le résultat du programme.', [('2*7',14)])
E(152,'Un programme en deux étapes','Choisir 4 ; ajouter 3 ; multiplier le résultat par 2.',[
A('Quel nombre obtient-on après l’addition ?','Exécuter la première opération. ',r'$4+3=7$.','7.','Calculer le résultat intermédiaire'),
A('Quel est le résultat final ?','Multiplier le résultat intermédiaire, pas le nombre initial.',r'$7\times2=14$.','14.','Poursuivre avec le bon nombre')], 'Chaque instruction utilise le résultat obtenu à l’étape précédente.', [('4+3',7),('7*2',14)])
E(152,'Coder un déplacement global','Sur un quadrillage, on part de A1. Les colonnes A, B, C, D, E vont vers la droite ; les lignes 1, 2, 3, 4, 5 vont vers le haut. Exécuter : droite de 3 cases ; haut de 2 cases.',[
A('Quel point atteint-on après le premier ordre ?','Changer de colonne sans changer de ligne.','Depuis A1, trois cases vers la droite mènent à D1.','D1.','Exécuter le déplacement horizontal'),
A('Où arrive-t-on à la fin ?','Garder la colonne puis changer de ligne.','Depuis D1, deux cases vers le haut mènent à D3.','D3.','Exécuter le déplacement vertical')], 'Dans ce codage global, « haut » désigne toujours le haut de la feuille.',images=('chemin_L_vide','chemin_L'))
E(152,'Répéter une addition','On part de 2 et on répète trois fois « ajouter 4 au résultat courant ».',[
A('Écrire les résultats successifs.','Reprendre chaque fois le dernier nombre obtenu.',r'$2+4=6$, puis $6+4=10$, puis $10+4=14$.','6 ; 10 ; 14.','Exécuter les trois passages'),
A('Combien d’additions ont été faites ?','Compter les passages dans le bloc.','L’instruction répétée est exécutée trois fois.','3 additions.','Compter les répétitions')], 'Le nombre de répétitions compte les passages, pas la valeur du résultat.', [('2+4',6),('6+4',10),('10+4',14)])
E(152,'Tourner n’est pas avancer','Un robot est orienté vers le haut. Il tourne d’un quart de tour à droite, sans avancer.',[
A('Vers où regarde-t-il ?','Faire tourner l’orientation dans le sens indiqué.','Depuis le haut, un quart de tour à droite mène vers la droite de la feuille.','Vers la droite.','Mettre à jour l’orientation'),
A('A-t-il changé de case ?','Distinguer orientation et position.','Aucun ordre de déplacement n’a été exécuté.','Non.','Conserver la position')], 'Une rotation change l’orientation ; un déplacement change la position.')
E(152,'Compresser une séquence','Le programme exécute : avancer de 2 cases ; avancer de 2 cases ; avancer de 2 cases ; avancer de 2 cases, toujours dans le même sens.',[
A('L’écrire avec une répétition.','Identifier le bloc identique et son nombre d’occurrences.','Le même ordre apparaît quatre fois.','Répéter 4 fois : avancer de 2 cases.','Repérer le bloc répété'),
A('Quelle distance est parcourue ?','Additionner les quatre déplacements identiques.',r'$4\times2=8$.','8 cases.','Calculer la distance totale')], 'Une écriture plus courte doit conserver exactement les mêmes actions.', [('4*2',8)])
E(152,'Dessiner un carré','Un robot part orienté vers la droite, crayon baissé. Il répète 4 fois : avancer de 3 cases ; tourner d’un quart de tour à gauche.',[
A('Quelle figure trace-t-il ?','Suivre les quatre côtés et les changements d’orientation.','Il trace un côté vers la droite, puis vers le haut, puis vers la gauche, puis vers le bas.','Un carré de côté 3 cases.','Suivre les quatre côtés'),
A('Quelle distance parcourt-il ?','Compter les quatre déplacements.',r'$4\times3=12$.','12 cases ; il revient au départ.','Mesurer le trajet')], 'Le dernier quart de tour ne trace aucun côté supplémentaire.', [('4*3',12)],images=('carre_vide','carre'))
E(152,'Corriger un carré ouvert','Un robot, orienté vers la droite, répète 3 fois : avancer de 3 cases ; tourner d’un quart de tour à gauche.',[
A('Pourquoi le carré n’est-il pas fermé ?','Comparer le nombre de côtés tracés aux quatre côtés attendus.','Trois répétitions tracent seulement trois côtés.','Il manque le quatrième côté.','Diagnostiquer la boucle'),
A('Corriger le programme.','Modifier le nombre de répétitions.','Répéter quatre fois les mêmes deux instructions trace le dernier côté et ferme le carré.','Remplacer 3 répétitions par 4.','Réparer la répétition')], 'Un test du tracé permet de vérifier la fermeture de la figure.',images=('carre_ouvert','carre'))
E(152,'Un escalier régulier','Sur le quadrillage, partir de A1 et répéter 3 fois : droite de 1 case ; haut de 1 case.',[
A('Quel est le point d’arrivée ?','Cumuler séparément les déplacements horizontaux et verticaux.','Trois cases à droite mènent de A à D ; trois cases vers le haut mènent de 1 à 4.','D4.','Suivre les deux directions'),
A('Quelle distance a-t-on parcourue ?','Chaque répétition comporte deux pas.',r'$3\times(1+1)=6$.','6 cases.','Compter tous les pas')], 'La longueur du trajet ne se lit pas sur le segment direct entre départ et arrivée.', [('3*(1+1)',6)],images=('escalier_vide','escalier'))
E(152,'Deux ordres de calcul','A : ajouter 3 puis multiplier par 2. B : multiplier par 2 puis ajouter 3. L’entrée vaut 5.',[
A('Calculer la sortie de A.','Respecter l’ordre annoncé.',r'$5+3=8$, puis $8\times2=16$.','16.','Exécuter A'),
A('Calculer B puis comparer.','Refaire les opérations dans l’autre ordre.',r'$5\times2=10$, puis $10+3=13$. Les sorties 16 et 13 diffèrent.','13 ; les programmes ne sont pas équivalents.','Exécuter B')], 'Changer l’ordre des mêmes opérations peut changer le résultat.', [('5+3',8),('8*2',16),('5*2',10),('10+3',13)])
E(152,'Répéter un bloc entier','On part de 1. Répéter 2 fois le bloc « ajouter 2 ; multiplier par 3 ».',[
A('Quel résultat obtient-on à la fin du premier passage ?','Exécuter les deux instructions du bloc.',r'$1+2=3$, puis $3\times3=9$.','9.','Exécuter le premier bloc'),
A('Quel est le résultat final ?','Repartir de 9 pour le deuxième bloc.',r'$9+2=11$, puis $11\times3=33$.','33.','Exécuter le second bloc')], 'Une répétition porte sur toutes les instructions placées dans son bloc.', [('1+2',3),('3*3',9),('9+2',11),('11*3',33)])
E(152,'Tester plusieurs entrées','Un programme affiche « 3 × entrée + 1 ».',[
A('Calculer les sorties pour les entrées 0 et 4.','Substituer chaque entrée séparément.',r'$3\times0+1=1$ ; $3\times4+1=13$.','1 et 13.','Tester deux valeurs'),
A('L’entrée 3 donne-t-elle la sortie 10 ?','Tester la proposition dans le programme.',r'$3\times3+1=10$.','Oui.','Vérifier une paire entrée-sortie')], 'Tester plusieurs entrées aide à comprendre le rôle du calcul.', [('3*0+1',1),('3*4+1',13),('3*3+1',10)])
E(152,'Une suite évolutive','Une suite commence par 3. Pour obtenir chaque terme suivant, on ajoute 5.',[
A('Donner les quatre termes suivants.','Appliquer la même instruction au dernier terme.',r'$3+5=8$, puis 13, 18 et 23.','8 ; 13 ; 18 ; 23.','Répéter la règle'),
A('Combien de fois a-t-on ajouté 5 pour atteindre 23 ?','Compter les passages de terme en terme.','On passe de 3 à 8, puis 13, puis 18, puis 23.','4 fois.','Compter les transitions')], 'Le premier terme est déjà présent avant la première répétition.', [('3+5',8),('3+4*5',23)])
E(152,'Programmer un rectangle','Un robot orienté vers la droite doit tracer un rectangle de 4 cases sur 2 cases et revenir au départ.',[
A('Proposer un bloc à répéter deux fois.','Associer un long côté, un court côté et leurs deux rotations.','Avancer de 4 ; tourner d’un quart de tour à gauche ; avancer de 2 ; tourner d’un quart de tour à gauche. Répéter ce bloc 2 fois.','Deux répétitions du bloc proposé.','Construire le motif de deux côtés'),
A('Quelle distance est parcourue ?','Compter les deux longueurs et les deux largeurs.',r'$2\times(4+2)=12$.','12 cases.','Vérifier le périmètre')], 'Le bloc répété doit contenir le second virage pour changer de côté correctement.', [('2*(4+2)',12)],images=('rectangle_vide','rectangle'))
E(152,'Un détour autour d’un obstacle','Sur le quadrillage, on part de A1 vers D1. La case B1 est interdite. On propose : haut de 1 ; droite de 3 ; bas de 1.',[
A('Ce chemin atteint-il D1 sans passer par B1 ?','Suivre tous les points intermédiaires.','Le chemin passe par A2, puis D2 et enfin D1. Il ne traverse pas B1.','Oui.','Vérifier le détour'),
A('Quelle distance supplémentaire parcourt-on par rapport au chemin direct de 3 cases ?','Comparer les longueurs des deux trajets.',r'$1+3+1=5$ cases ; $5-3=2$.','2 cases supplémentaires.','Mesurer le coût du détour')], 'Un programme de chemin doit respecter les obstacles, pas seulement l’arrivée.', [('1+3+1',5),('5-3',2)],images=('detour_vide','detour'))
E(152,'Déboguer une direction','Un robot doit aller de A1 à C3. Le programme saisi est « droite de 2 ; bas de 2 ». Les lignes augmentent vers le haut.',[
A('Quelle instruction contient l’erreur ?','Comparer le mouvement vertical à l’arrivée attendue.','Pour passer de la ligne 1 à la ligne 3, il faut monter et non descendre.','« bas de 2 ».','Identifier la direction erronée'),
A('Donner le programme corrigé.','Conserver le déplacement horizontal correct.','Droite de 2 amène en C1 ; haut de 2 amène en C3.','Droite de 2 ; haut de 2.','Corriger et tester')], 'Corriger la première instruction fautive, puis reprendre le test depuis le départ.',images=('bug_vide','bug_corrige'))
E(152,'Un compteur de motifs','Un motif contient 2 triangles et 1 carré. On répète ce motif 5 fois, sans chevauchement.',[
A('Combien de triangles et de carrés obtient-on ?','Multiplier chaque quantité du motif par le nombre de copies.',r'$5\times2=10$ triangles ; $5\times1=5$ carrés.','10 triangles et 5 carrés.','Dénombrer les copies'),
A('Combien de figures sont dessinées en tout ?','Additionner les deux familles.',r'$10+5=15$.','15 figures.','Contrôler le total')], 'Le bloc répété peut contenir plusieurs types d’objets.', [('5*2',10),('5*1',5),('10+5',15)])
E(152,'Une donnée ne change pas toute seule','Un programme demande une entrée, puis affiche entrée + 2 et ensuite entrée × 3. Il n’y a aucun ordre qui modifie l’entrée. On saisit 4.',[
A('Qu’affiche-t-il en premier ?','Lire la valeur saisie.',r'$4+2=6$.','6.','Calculer le premier affichage'),
A('Qu’affiche-t-il ensuite : 12 ou 18 ?','Réutiliser l’entrée 4, qui n’a pas changé.',r'$4\times3=12$. Le premier affichage n’a pas remplacé la donnée.','12.','Distinguer affichage et modification')], 'Afficher un calcul ne modifie pas automatiquement la donnée d’entrée.', [('4+2',6),('4*3',12)])
E(152,'Limiter le nombre de pas','Un escalier répète « droite de 2 cases ; haut de 1 case ». Le budget est de 12 cases parcourues.',[
A('Combien de répétitions complètes peut-on effectuer ?','Calculer le coût d’un motif puis partager le budget.',r'$2+1=3$ cases par motif ; $12\div3=4$.','4 répétitions.','Gérer le budget de déplacement'),
A('Depuis A1, où arrive-t-on ?','Cumuler les déplacements de quatre motifs.','On avance de 8 colonnes, de A à I, et de 4 lignes, de 1 à 5.','I5.','Vérifier la position finale')], 'La distance totale compte les pas horizontaux et verticaux.', [('2+1',3),('12/3',4),('4*2',8),('4*1',4)])
E(152,'Un petit projet autonome','On veut saisir un nombre, lui ajouter 2, doubler le résultat puis afficher la sortie.',[
A('Écrire une séquence claire.','Séparer la lecture, les calculs et l’affichage.','Demander un nombre ; ajouter 2 au nombre saisi ; multiplier ce résultat par 2 ; afficher le résultat final.','La séquence proposée respecte l’objectif.','Organiser le programme'),
A('Tester avec l’entrée 6 et repérer l’erreur si on obtient 14.','Comparer l’exécution attendue à une exécution dans le mauvais ordre.',r'Attendu : $6+2=8$, puis $8\times2=16$. La sortie 14 correspond à $6\times2+2$.','16 ; une sortie 14 révèle un ordre de calcul incorrect.','Tester et diagnostiquer')], 'Un programme est contrôlé avec des entrées choisies et des sorties attendues.', [('6+2',8),('8*2',16),('6*2+2',14)])
